pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 amount, uint256 collectAmt) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.Put{value: amount}(lockTime) {} catch { return; }
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        uint beforeCEther = address(c).balance;
        bool reverted;
        try c.Collect(collectAmt) { reverted = false; } catch { reverted = true; }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        uint afterCEther = address(c).balance;
        assertTrue(!reverted || (afterBalance == beforeBalance && afterUnlock == beforeUnlock && afterCEther == beforeCEther));
    }

    function testFuzz_run(uint256 lockTime, uint256 amount, uint256 collectAmt) public {
        _run(lockTime, amount, collectAmt);
    }

    receive() external payable {}
}
